import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.BvlN9b-o.js";const m=JSON.parse('{"title":"Remove built-in business code while preserving SaaS Core","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/example-removal","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/example-removal.md","filePath":"en/tutorials/example-removal.md"}'),n={name:"en/tutorials/example-removal.md"};function o(r,e,d,l,p,h){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="remove-built-in-business-code-while-preserving-saas-core" tabindex="-1">Remove built-in business code while preserving SaaS Core <a class="header-anchor" href="#remove-built-in-business-code-while-preserving-saas-core" aria-label="Permalink to &quot;Remove built-in business code while preserving SaaS Core&quot;">​</a></h1><p>Remove the knowledge business from your template working copy while accounts, Memberships, Sessions, Files, Jobs, notifications, Audit, mail, API Keys, rate limiting and telemetry remain available to your SaaS. Example Removal changes source and derived artifacts; it does not delete production databases, objects or secrets.</p><p>You need a clean Git working copy and the installed toolchain. Run commands from the repository root. Save your edits or rehearse in an independent temporary copy before applying removal.</p><h2 id="inspect-ownership-and-preview" tabindex="-1">Inspect ownership and preview <a class="header-anchor" href="#inspect-ownership-and-preview" aria-label="Permalink to &quot;Inspect ownership and preview&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-remove</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span></code></pre></div><p>The default id is <code>knowledge-base</code>. The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/scripts/example-remove.mjs" target="_blank" rel="noreferrer">tool</a> reads <code>examples/&lt;id&gt;/manifest.json</code> and lists paths, registration blocks, documentation entries, exclusive dependencies and regeneration commands without writing files.</p><table tabindex="0"><thead><tr><th>Manifest field</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ownedPaths</code></td><td>Exclusive source, tests, migrations and bilingual teaching pages</td></tr><tr><td><code>registrationMarkers</code></td><td>Paired <code>example:&lt;prefix&gt;:&lt;marker&gt;:start/end</code> blocks in shared assembly files</td></tr><tr><td><code>compositionPoints</code></td><td>API, Worker, Web and documentation entries to edit rather than delete</td></tr><tr><td><code>ownedDependencies</code> / <code>ownedCargoDependencies</code></td><td>Dependencies exclusive to this business</td></tr><tr><td><code>retainedMigrations</code></td><td>Historical migrations preserved after code removal</td></tr></tbody></table><p>Conflicting ownership, missing/duplicate markers, unknown ids and uncommitted changes prevent actual removal. Resolve ownership or save edits as reported; do not disable safeguards around your customizations.</p><h2 id="choose-a-migration-history-policy" tabindex="-1">Choose a migration-history policy <a class="header-anchor" href="#choose-a-migration-history-policy" aria-label="Permalink to &quot;Choose a migration-history policy&quot;">​</a></h2><p>For a project with applied or published migrations, use the default:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-remove</span></span></code></pre></div><p>Business code and registration disappear while historical migrations remain under <code>retainedMigrations</code>. Existing tables/data and the source migration set/checksums remain intact. Plan production data removal separately through new migrations, object cleanup and Audit; do not delete applied migration files.</p><p>A fresh project that has never created a database may use:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-remove</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trim-migrations</span></span></code></pre></div><p>This trims example migrations so a new empty database initializes from Core. The tool does not inspect databases to prove this condition; you must establish it. Existing databases cannot use the trimmed path.</p><h2 id="verify-the-reduced-application" tabindex="-1">Verify the reduced application <a class="header-anchor" href="#verify-the-reduced-application" aria-label="Permalink to &quot;Verify the reduced application&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-core</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs-build</span></span></code></pre></div><p>Removal regenerates lockfiles, contracts/SDK and documentation references. Check compilation, real Core HTTP/task behavior, boundaries, frontend and documentation builds, then run your own business tests.</p><p>Universal home, identity pages and settings remain. Historical notifications for removed features stay readable and can be marked read, while their targets are unavailable. Old business links provide recoverable unavailable feedback; historical records do not imply an API still exists. Removing the selected business Default Entry falls back to universal home, and direct <code>/</code> always remains universal home.</p><p>Backup/restore tools remain usable. Reference-specific production smoke, restore drills and load scenarios explain and exit when the example is absent. Replace them with your own business assertions; a skip is not acceptance.</p><h2 id="add-or-remove-another-reference-business" tabindex="-1">Add or remove another reference business <a class="header-anchor" href="#add-or-remove-another-reference-business" aria-label="Permalink to &quot;Add or remove another reference business&quot;">​</a></h2><p>The shipped notes example proves UI composition only. It is unregistered by default and has no notes backend. Both add and remove require a clean copy. Validate and commit your changes after each operation before the next:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-add.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-remove.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-remove.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes</span></span></code></pre></div><p>Unregistered notes lacks required markers and cannot be removed directly as a whole. Add it first, then remove it, or handle ownership manually. All contributions still belong to one Organization; see the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/adr/0003-static-example-composition.md" target="_blank" rel="noreferrer">source-composition ADR</a>.</p><h2 id="start-your-own-module" tabindex="-1">Start your own module <a class="header-anchor" href="#start-your-own-module" aria-label="Permalink to &quot;Start your own module&quot;">​</a></h2><p>Use <a href="./../guides/new-module">Add a business module</a> to compose Router/OpenAPI, then add an owned schema, migration and <code>module.json</code>. Access identity, Memberships, Files, Audit and Jobs through public interfaces. Register outside any removed business&#39;s markers.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/scripts/example-new-business.mjs" target="_blank" rel="noreferrer">new-business exercise</a> creates a real backend notes module, migration and HTTP tests in a copy without knowledge, verifying registration, creation and reading. It is a development exercise distinct from shipped UI-only notes. It modifies its target and needs Docker/PostgreSQL; do not run it repeatedly in a production working copy:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/example-new-business.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/my-clean-core-copy</span></span></code></pre></div><p>Replace <code>/tmp/my-clean-core-copy</code> with your prepared removal exercise copy.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/example-remove.test.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span></code></pre></div><p>Tool tests cover exact deletion, dry-run, migration history, dependency/navigation trimming and refusal behavior. Next: continue backend work with <a href="./../guides/new-module">Add a module</a>, or <a href="./add-example">application-shell contributions</a> when adding Web pages.</p><hr><p>Source version：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/tutorials/23-example-removal.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,34)])])}const u=a(n,[["render",o]]);export{m as __pageData,u as default};
